--
-- Table structure for table `order_items`
--

DROP TABLE IF EXISTS `order_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `order_items` (
  `order_id` char(32) NOT NULL,
  `merchant_id` char(32) NOT NULL,
  `product_id` char(32) NOT NULL,
  `variant_id` char(32) DEFAULT NULL,
  `quantity` int NOT NULL,
  `unit_price` bigint NOT NULL,
  `currency` char(3) NOT NULL,
  `line_total` bigint NOT NULL,
  `id` char(32) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `variant_id` (`variant_id`),
  KEY `ix_order_items_order_id` (`order_id`),
  KEY `idx_order_items_merchant` (`merchant_id`),
  KEY `idx_order_items_product` (`product_id`),
  KEY `ix_order_items_merchant_id` (`merchant_id`),
  KEY `idx_order_items_order` (`order_id`),
  CONSTRAINT `order_items_ibfk_1` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE,
  CONSTRAINT `order_items_ibfk_2` FOREIGN KEY (`merchant_id`) REFERENCES `merchants` (`id`) ON DELETE CASCADE,
  CONSTRAINT `order_items_ibfk_3` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE,
  CONSTRAINT `order_items_ibfk_4` FOREIGN KEY (`variant_id`) REFERENCES `product_variants` (`id`),
  CONSTRAINT `ck_order_items_line_total_non_negative` CHECK ((`line_total` >= 0)),
  CONSTRAINT `ck_order_items_quantity_positive` CHECK ((`quantity` > 0)),
  CONSTRAINT `ck_order_items_unit_price_non_negative` CHECK ((`unit_price` >= 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
