  `status` varchar(50) NOT NULL,
  `currency` char(3) NOT NULL,
  `total_amount` bigint NOT NULL,
  `idempotency_key` varchar(255) DEFAULT NULL,
  `id` char(32) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `order_number` varchar(50) NOT NULL,
  `fulfilled_at` datetime DEFAULT NULL,
  `fulfillment_summary` text,
  `delivery_address` json DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ix_orders_order_number` (`order_number`),
  UNIQUE KEY `uq_orders_idempotency_key` (`idempotency_key`),
  UNIQUE KEY `idempotency_key` (`idempotency_key`),
  KEY `idx_orders_buyer` (`buyer_id`),
  KEY `idx_orders_status` (`status`),
  KEY `idx_orders_created_at` (`created_at` DESC),
  CONSTRAINT `orders_ibfk_1` FOREIGN KEY (`buyer_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `ck_orders_total_non_negative` CHECK ((`total_amount` >= 0))
