INSERT INTO `products` VALUES ('7a6d064d2b5e4f0481076e56067693ae','4a40e0ec05394e2a9bf5e4156061b703','4227f6f6c02711f1b2c3f430b918329f','Crystal Shine Bleach – Powerful Stain Remover, Whitening & Household Cleaning Solution','crystal-shine-bleach','✨ CRYSTAL SHINE BLEACH\n\nExperience effective cleaning and whitening with Crystal Shine Bleach! Designed to help remove tough stains, brighten suitable white fabrics and maintain household cleanliness.\n\nWHY CHOOSE CRYSTAL SHINE BLEACH?\n\n* Helps remove stubborn stains.\n* Whitens suitable white fabrics.\n* Supports household cleaning and sanitation.\n* Easy and convenient to use.\n* Affordable cleaning solution.\n\nDIRECTIONS FOR USE:\n\n1. Dilute with water according to the recommended product instructions.\n2. Apply to suitable surfaces or white fabrics.\n3. Allow the recommended contact time.\n4. Rinse thoroughly with clean water.\n\nSAFETY INFORMATION:\n\n* Keep out of reach of children.\n* Wear protective gloves when handling.\n* Avoid contact with eyes and skin.\n* Do not swallow or inhale fumes.\n* Never mix with acids, toilet cleaners, ammonia or other cleaning products.\n* Use in a well-ventilated area.\n* Store tightly closed in a cool, shaded place.\n* If swallowed or splashed into the eyes, seek immediate medical attention.\n\nCRYSTAL SHINE – Making Cleanliness Beautiful!','physical','active',200000,'NGN','{}','4b6f188fde98429cad415109ac742b45','2026-11-25 13:01:52','2026-11-25 13:23:52','[\"https://markto-119826413303-eu-north-1-an.s3.eu-north-1.amazonaws.com/product_image/7a6d064d-2b5e-4f04-8107-6e56067693ae/4a9f5ce21aee4b088e386a536a305eec.jpeg\", \"https://markto-119826413303-eu-north-1-an.s3.eu-north-1.amazonaws.com/product_image/7a6d064d-2b5e-4f04-8107-6e56067693ae/14868755670b4c7093a04b32e75a31e0.jpeg\", \"https://markto-119826413303-eu-north-1-an.s3.eu-north-1.amazonaws.com/product_image/7a6d064d-2b5e-4f04-8107-6e56067693ae/281f985efa3641c484438d81ea146734.jpeg\"]'),('7a6d064d2b5e4f0481076e56067693ae','4a40e0ec05394e2a9bf5e4156061b703','4227f6f6c02711f1b2c3f430b918329f','Crystal Shine Powerful Toilet Wash – Deep Cleaning & Stain Removal Solution','crystalshine-toilet-wash','✨ CRYSTAL SHINE TOILET WASH\n\nKeep your toilet sparkling clean and fresh with Crystal Shine Toilet Wash! Its effective cleaning formula helps remove stubborn stains, dirt and grime while tackling unpleasant odours.\n\nWhy Choose Crystal Shine?\n\n* Helps remove tough toilet stains.\n* Fights dirt and grime.\n* Helps eliminate unpleasant odours.\n* Easy to use and effective.\n* Affordable everyday cleaning solution.\n\nCrystal Shine – Making Cleanliness Beautiful!','physical','active',300000,'NGN','{}','4fad39e4e4e74934affcc2afdb158a86','2026-11-25 12:46:02','2026-11-25 13:21:55','[\"https://markto-119826413303-eu-north-1-an.s3.eu-north-1.amazonaws.com/product_image/7a6d064d-2b5e-4f04-8107-6e56067693ae/479d82cc099d4e1a85acd19e82209f45.png\", \"https://markto-119826413303-eu-north-1-an.s3.eu-north-1.amazonaws.com/product_image/7a6d064d-2b5e-4f04-8107-6e56067693ae/df6825c6371043c78047febf6233facf.jpeg\", \"https://markto-119826413303-eu-north-1-an.s3.eu-north-1.amazonaws.com/product_image/7a6d064d-2b5e-4f04-8107-6e56067693ae/22146fba12fb4fc6976411ea8845ca4b.jpeg\", \"https://markto-119826413303-eu-north-1-an.s3.eu-north-1.amazonaws.com/product_image/7a6d064d-2b5e-4f04-8107-6e56067693ae/fefe719e69464101b2e69d8cef8ecbe6.jpeg\", \"https://markto-119826413303-eu-north-1-an.s3.eu-north-1.amazonaws.com/product_image/7a6d064d-2b5e-4f04-8107-6e56067693ae/fc21ff870ad749a69e8c408445da947c.jpeg\"]'),('7a6d064d2b5e4f0481076e56067693ae','4a40e0ec05394e2a9bf5e4156061b703','4227f6f6c02711f1b2c3f430b918329f','Crystal Shine Multipurpose Liquid Detergent -Powerful Everyday Cleaning Solution','crystal-shine-multipurpose-liquid-detergent-powerful-everyday-cleaning-solution','✨ CLEAN SMARTER. SHINE BRIGHTER!\n\nExperience effortless cleaning with Crystal Shine Multipurpose Liquid Detergent – your reliable partner for a cleaner, fresher and sparkling environment.\n\nDesigned to help remove everyday dirt, grease and stains, Crystal Shine makes household cleaning easier and more convenient.\n\nWhy Choose Crystal Shine?\n\n* Effective cleaning power.\n* Helps remove dirt and grease.\n* Suitable for various household cleaning tasks.\n* Affordable and easy to use.\n* Perfect for everyday cleaning.\n\nGive your home the Crystal Shine treatment!\n\nCrystal Shine – Making Cleanliness Beautiful!','physical','active',150000,'NGN','{}','697cdc9556944804aab799ade1e31701','2026-11-25 12:38:57','2026-11-25 13:09:23','[\"https://markto-119826413303-eu-north-1-an.s3.eu-north-1.amazonaws.com/product_image/7a6d064d-2b5e-4f04-8107-6e56067693ae/4c91e68805b34776855624938596d211.jpeg\", \"https://markto-119826413303-eu-north-1-an.s3.eu-north-1.amazonaws.com/product_image/7a6d064d-2b5e-4f04-8107-6e56067693ae/e00074a3972c4a6c8dbbc8b29c836f5a.jpeg\", \"https://markto-119826413303-eu-north-1-an.s3.eu-north-1.amazonaws.com/product_image/7a6d064d-2b5e-4f04-8107-6e56067693ae/d6edaa7219ec472e8757c2b5e1c42b07.jpeg\", \"https://markto-119826413303-eu-north-1-an.s3.eu-north-1.amazonaws.com/product_image/7a6d064d-2b5e-4f04-8107-6e56067693ae/71584e5179834de6ae30931c48e35579.jpeg\", \"https://markto-119826413303-eu-north-1-an.s3.eu-north-1.amazonaws.com/product_image/7a6d064d-2b5e-4f04-8107-6e56067693ae/0ab78acb5a73448892d46982d8d21fa8.jpeg\", \"https://markto-119826413303-eu-north-1-an.s3.eu-north-1.amazonaws.com/product_image/7a6d064d-2b5e-4f04-8107-6e56067693ae/60f947b249f348ccbf1414c4442bb063.jpeg\"]'),('0db11729c5fb48e09ea654d893fdb2f0','6c26ef4cb3394168ae279a4590ad8665','370a991ad2b511f1aa26063f69b46fea','The Tithe Controversy','the-tithe-controversy','An exposition into the origins and history of tithing.','digital','active',165000,'NGN','{}','b5aef056ff4a42309f0e632202203156','2026-10-28 13:58:26','2026-11-16 13:58:58','[\"https://markto-119826413303-eu-north-1-an.s3.eu-north-1.amazonaws.com/product_image/0db11729-c5fb-48e0-9ea6-54d893fdb2f0/bc212a00da8e403d981d2a0db17187cb.png\", \"https://markto-119826413303-eu-north-1-an.s3.eu-north-1.amazonaws.com/product_image/0db11729-c5fb-48e0-9ea6-54d893fdb2f0/a14c7371d83844df94fc199976323c15.png\"]'),('7a6d064d2b5e4f0481076e56067693ae','4a40e0ec05394e2a9bf5e4156061b703','4227f6f6c02711f1b2c3f430b918329f','Crystal Shine Tiles Care – Powerful Tile Cleaner for Deep Cleaning & Lasting Freshness','crystal-shine-tiles-care','✨ CRYSTAL SHINE TILES CARE\n\nGive your floors the care they deserve with Crystal Shine Tiles Care! Its effective cleaning formula helps remove dirt, stains and everyday grime, leaving your tiles looking clean, bright and refreshed.\n\nWHY CHOOSE CRYSTAL SHINE?\n\n* Helps remove stubborn dirt and stains.\n* Cleans everyday tile grime.\n* Leaves tiles looking fresh and clean.\n* Easy and convenient to use.\n* Affordable cleaning solution.\n\nDIRECTIONS FOR USE:\n\n1. Dilute with water according to the product label.\n2. Apply to the tiled surface using a mop or cleaning cloth.\n3. Gently scrub areas with stubborn dirt.\n4. Rinse with clean water if necessary.\n5. Allow the floor to dry.\n\nSAFETY INFORMATION:\n\n* Keep out of reach of children.\n* Avoid contact with eyes and skin.\n* Wear protective gloves when using.\n* Do not swallow.\n* Do not mix with bleach or other cleaning chemicals.\n* Store in a cool, dry place.\n* If swallowed or if irritation occurs, seek medical attention.\n\nCRYSTAL SHINE – Making Cleanliness Beautiful!','physical','active',300000,'NGN','{}','e54b0039a1f0445487c3d6fe827569b1','2026-11-25 12:59:01','2026-11-25 13:23:01','[\"https://markto-119826413303-eu-north-1-an.s3.eu-north-1.amazonaws.com/product_image/7a6d064d-2b5e-4f04-8107-6e56067693ae/90b0db83153d4e2bb5fbde3881e61598.jpeg\", \"https://markto-119826413303-eu-north-1-an.s3.eu-north-1.amazonaws.com/product_image/7a6d064d-2b5e-4f04-8107-6e56067693ae/cfb2c1e1ece347db8aec8e33f3d94545.jpeg\", \"https://markto-119826413303-eu-n